#!/usr/bin/env python3
# PS5 13.60 QEMU kernel builder: applies a patch set to the public 13.60 dump
# (terrafirma2021/ps5-13.60-kernel-dump) and produces wp3_boot/kernel_raw.bin
# Usage: python3 build_kernel.py <path/to/kernel-13.60-live.bin>
import ast, base64, hashlib, os, sys, zlib

KSIZE      = 65224704
BASE_MD5   = "ca43f306298bab963974f2c2b028f4b8"
TARGET_MD5 = "520808c90b58241f454baeae0db0c8cc"
PATCH_B64  = ""

def main():
    src = sys.argv[1] if len(sys.argv) > 1 else "wp3_boot/kernel_raw.bin"
    dst = "wp3_boot/kernel_raw.bin"
    if not os.path.exists(src):
        sys.exit("[!] input not found: " + src)
    raw = open(src, "rb").read()
    if len(raw) < KSIZE:
        sys.exit("[!] input too small: %d < %d" % (len(raw), KSIZE))
    buf = bytearray(raw[:KSIZE])
    cur = hashlib.md5(buf).hexdigest()
    if cur == TARGET_MD5:
        print("[+] already patched and verified"); return
    if cur != BASE_MD5:
        sys.exit("[!] base dump MD5 mismatch: got %s, expected %s" % (cur, BASE_MD5))
    for off, chunk in ast.literal_eval(zlib.decompress(base64.b64decode(PATCH_B64)).decode("ascii")):
        buf[off:off + len(chunk)] = chunk
    md5 = hashlib.md5(buf).hexdigest()
    assert md5 == TARGET_MD5, "hash mismatch: %s" % md5
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    open(dst, "wb").write(buf)
    print("[+] built", dst, "MD5", md5)

if __name__ == "__main__":
    main()
